-- +goose Up
-- Ten showcase reading plans. Each day: whole-chapter readings, a reflection and a prayer.
-- Covers are the bright Shekinah design served by the API. Members are not notified
-- (the publication notifications these inserts queue are marked as already sent).
UPDATE publication_notifications SET processed_at = NOW() WHERE kind = 'plans' AND processed_at IS NULL AND item_id IN ('plan-sons-of-god-21', 'plan-shekinah-glory-14', 'plan-holy-spirit-21', 'plan-prayer-14', 'plan-heroes-of-faith-12', 'plan-fruit-of-the-spirit-9', 'plan-names-of-god-10', 'plan-david-14', 'plan-stewardship-10', 'plan-cross-and-tomb-8');
-- Existing plans without a picture get the same bright cover.
UPDATE reading_plans SET image_url = 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/' || id || '.jpg' WHERE image_url = '';
UPDATE publication_notifications SET processed_at = NOW() WHERE kind = 'plans' AND processed_at IS NULL;

-- +goose Down
DELETE FROM reading_plans WHERE id IN ('plan-sons-of-god-21', 'plan-shekinah-glory-14', 'plan-holy-spirit-21', 'plan-prayer-14', 'plan-heroes-of-faith-12', 'plan-fruit-of-the-spirit-9', 'plan-names-of-god-10', 'plan-david-14', 'plan-stewardship-10', 'plan-cross-and-tomb-8');
