INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-sons-of-god-21', 'Sons of God: Identity in Christ', 'Twenty-one days discovering who you are in Christ: chosen, adopted, loved and sent. Each day pairs a key chapter with a reflection and a prayer, so the truth of sonship moves from your head into your daily walk.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-sons-of-god-21.jpg', 21, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d1', 'plan-sons-of-god-21', 1, 'Created for His image', 'Genesis 1-2', 'Before you did anything, God called you very good and made you in His image (Genesis 1:26-27). Your identity starts with His design, not your performance.', 'Father, thank You that I was made on purpose and in Your image. Teach me to see myself as You see me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d2', 'plan-sons-of-god-21', 2, 'The image lost', 'Genesis 3', 'Sin brought hiding, shame and blame. Yet God came looking: ''Where are you?'' (3:9). Even in the fall He promised a Seed who would crush the serpent (3:15).', 'Lord, where I have hidden from You, I come out into Your light. Thank You for pursuing me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d3', 'plan-sons-of-god-21', 3, 'Chosen before the world began', 'Ephesians 1', 'You were chosen in Him before the foundation of the world and adopted as a son through Jesus Christ (1:4-5). Your belonging was settled in eternity.', 'Father, thank You for choosing me. Let the spirit of wisdom and revelation open my eyes to my inheritance.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d4', 'plan-sons-of-god-21', 4, 'From dead to seated', 'Ephesians 2', 'We were dead in sin, but God, rich in mercy, made us alive and seated us with Christ in heavenly places (2:4-6). You are His workmanship, created for good works.', 'Lord, thank You for raising me with Christ. Show me the good works You prepared for me today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d5', 'plan-sons-of-god-21', 5, 'The Spirit of adoption', 'Romans 8', 'You did not receive a spirit of slavery to fear, but the Spirit of adoption by whom we cry, ''Abba, Father!'' (8:15). Nothing can separate you from His love (8:38-39).', 'Abba Father, I receive Your Spirit of sonship. Drive out every fear and assure my heart that I am Yours.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d6', 'plan-sons-of-god-21', 6, 'No longer a slave', 'Galatians 3-4', 'In Christ you are a son and an heir (4:7). The law was a guardian until faith came; now you live from the Father''s house, not the servants'' quarters.', 'Father, free me from striving to earn what You have freely given. I live today as Your heir.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d7', 'plan-sons-of-god-21', 7, 'Born from above', 'John 1; John 3', 'To all who received Him He gave the right to become children of God (1:12). New birth is God''s work, by the Spirit, through faith in the Son (3:3-16).', 'Jesus, I receive You again today. Thank You for giving me new birth by Your Spirit.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d8', 'plan-sons-of-god-21', 8, 'Beloved before the ministry', 'Matthew 3-4', 'The Father said ''This is My beloved Son'' before Jesus preached one sermon (3:17). The enemy''s first attack was on that identity: ''If You are the Son of God...'' (4:3).', 'Father, let Your voice over me be louder than every accusation. I stand on what You have said.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d9', 'plan-sons-of-god-21', 9, 'The two sons', 'Luke 15', 'One son ran away, the other stayed but served like a hired worker. The Father ran to the one and pleaded with the other: ''Son, all that I have is yours'' (15:31).', 'Father, heal any orphan heart in me. Help me to rest in Your house as a son, not a servant.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d10', 'plan-sons-of-god-21', 10, 'Children of the light', '1 John 1-3', 'See what manner of love the Father has given us, that we should be called children of God (3:1). Sons walk in the light, love their brothers and keep themselves pure.', 'Lord, let my life show the family likeness. Help me walk in the light and love deeply.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d11', 'plan-sons-of-god-21', 11, 'The Son who brings many sons to glory', 'Hebrews 1-2', 'Jesus is the radiance of God''s glory (1:3), and He is not ashamed to call us brothers (2:11). He came to bring many sons to glory (2:10).', 'Jesus, thank You for calling me Your brother. Lead me into the glory You have prepared.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d12', 'plan-sons-of-god-21', 12, 'Discipline is a sign of sonship', 'Hebrews 12', 'God disciplines those He loves, as a father the son in whom he delights (12:6). His correction proves we belong and produces the peaceful fruit of righteousness.', 'Father, I welcome Your correction. Train me so I share Your holiness.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d13', 'plan-sons-of-god-21', 13, 'Sons who are led', 'Romans 12', 'Present your bodies as a living sacrifice and be transformed by the renewing of your mind (12:1-2). Sons are led by the Spirit and live as one body.', 'Lord, renew my mind today. Let my thoughts, words and choices agree with Your will.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d14', 'plan-sons-of-god-21', 14, 'Creation is waiting', 'Romans 8', 'Creation waits with eager longing for the revealing of the sons of God (8:19). Your sonship is not only personal comfort; it is God''s answer to a groaning world.', 'Father, reveal Your life through me in my family, work and city.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d15', 'plan-sons-of-god-21', 15, 'The mind of the Son', 'Philippians 2', 'Christ, though in the form of God, humbled Himself and became obedient to death (2:5-8). Sons of God shine like stars by doing all things without grumbling (2:14-15).', 'Jesus, give me Your humility. Let me shine without complaining.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d16', 'plan-sons-of-god-21', 16, 'Heirs of the promise', 'Genesis 15; Genesis 22', 'Abraham believed God and it was counted to him as righteousness (15:6). On Mount Moriah God provided the ram: a picture of the Son given for sons.', 'Lord, I believe Your promises. Teach me to trust You when You ask for my Isaac.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d17', 'plan-sons-of-god-21', 17, 'Joseph: the favoured son', 'Genesis 37; Genesis 39', 'Joseph''s coat of many colours made his brothers jealous; slavery and prison followed. Yet ''the Lord was with Joseph'' in every place (39:2, 21).', 'Father, when favour brings trials, remind me that You are with me and working.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d18', 'plan-sons-of-god-21', 18, 'Joseph: the son who forgave', 'Genesis 45; Genesis 50', '''You meant evil against me, but God meant it for good'' (50:20). A secure son can forgive because he trusts the Father''s purpose.', 'Lord, I release those who hurt me. Turn every painful story into a saving story.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d19', 'plan-sons-of-god-21', 19, 'Sons who reign', 'Revelation 21-22', '''He who overcomes shall inherit all things, and I will be his God and he shall be My son'' (21:7). The story ends with sons in the Father''s presence, seeing His face.', 'Father, fix my eyes on eternity. Help me overcome today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d20', 'plan-sons-of-god-21', 20, 'Kings and priests', '1 Peter 2; Revelation 1', 'You are a chosen generation, a royal priesthood (1 Peter 2:9), made kings and priests to God (Revelation 1:6). Sons carry both authority and intercession.', 'Lord, I take my place as a royal priest. Teach me to pray and to rule in love.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-sons-of-god-21-d21', 'plan-sons-of-god-21', 21, 'Sent as the Son was sent', 'John 17; John 20', '''As the Father has sent Me, I also send you'' (20:21). Jesus prayed that we would be one and that the world would know the Father''s love (17:23).', 'Father, send me. Fill me with Your Spirit and let others know You love them as You love Jesus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-shekinah-glory-14', 'The Shekinah Glory', 'Fourteen days tracing the glory of God''s presence from the burning bush to the New Jerusalem. Discover what the glory is, why it departed, how it returned in Jesus, and how it now rests on His people.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-shekinah-glory-14.jpg', 14, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d1', 'plan-shekinah-glory-14', 1, 'The bush that did not burn', 'Exodus 3', 'God''s presence turned ordinary ground into holy ground (3:5). The glory came with a name, ''I AM'', and a mission: to deliver His people.', 'Lord, meet me where I am today. Make this ordinary place holy ground.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d2', 'plan-shekinah-glory-14', 2, 'Pillar of cloud and fire', 'Exodus 13-14', 'The Lord went before Israel in a pillar of cloud by day and fire by night (13:21). His presence guided, protected and stood between them and the enemy.', 'Lord, go before me today. I will follow Your cloud and rest in Your fire.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d3', 'plan-shekinah-glory-14', 3, 'Show me Your glory', 'Exodus 33-34', 'Moses would not move without God''s presence (33:15) and prayed, ''Show me Your glory.'' God revealed His goodness and His name: merciful, gracious, abounding in love (34:6).', 'Lord, I don''t want to go anywhere without You. Show me Your glory and Your goodness.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d4', 'plan-shekinah-glory-14', 4, 'Glory fills the tabernacle', 'Exodus 40', 'When everything was done as the Lord commanded, the cloud covered the tent and the glory filled it so that Moses could not enter (40:34-35).', 'Lord, I offer You obedience as my preparation. Fill my life like You filled the tabernacle.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d5', 'plan-shekinah-glory-14', 5, 'Glory in the temple', '2 Chronicles 5-7', 'As the singers and trumpeters were as one, praising ''He is good, His mercy endures forever'', the house was filled with a cloud (5:13-14). Fire fell after Solomon prayed (7:1).', 'Lord, unite our church in praise. Let Your glory fill our worship.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d6', 'plan-shekinah-glory-14', 6, 'Ichabod: the glory departs', '1 Samuel 4', 'Israel treated the ark like a lucky charm and lost it. ''The glory has departed from Israel'' (4:21). God''s presence cannot be used; it must be honoured.', 'Lord, forgive me for treating Your presence casually. I honour You as holy.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d7', 'plan-shekinah-glory-14', 7, 'Holy, holy, holy', 'Isaiah 6', 'Isaiah saw the Lord high and lifted up; the whole earth is full of His glory (6:3). The vision brought conviction, cleansing and a commission: ''Here am I, send me.''', 'Lord, let me see You as You are. Touch my lips and send me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d8', 'plan-shekinah-glory-14', 8, 'The glory leaves the temple', 'Ezekiel 10-11', 'Step by step the glory moved from the temple to the threshold to the mountain east of the city. God does not linger where He is ignored, but He waits nearby.', 'Lord, search my heart for anything that grieves Your presence. Stay with me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d9', 'plan-shekinah-glory-14', 9, 'The glory returns', 'Ezekiel 43', 'Ezekiel saw the glory return from the east, and the earth shone with it (43:2). God promised to dwell among His people forever.', 'Lord, return to every dry place in my life. Make Your home with us again.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d10', 'plan-shekinah-glory-14', 10, 'The Word became flesh', 'John 1-2', 'The Word became flesh and tabernacled among us, and we beheld His glory, full of grace and truth (1:14). At Cana Jesus revealed His glory and His disciples believed (2:11).', 'Jesus, You are the glory of God among us. Let me behold You and believe.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d11', 'plan-shekinah-glory-14', 11, 'The mountain of transfiguration', 'Matthew 17; Luke 9', 'His face shone like the sun and a bright cloud overshadowed them (Matthew 17:2, 5). The Father''s instruction was simple: ''Hear Him.''', 'Father, I will listen to Your Son. Let His light change me as I spend time with Him.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d12', 'plan-shekinah-glory-14', 12, 'Tongues of fire', 'Acts 1-2', 'The fire that rested on the tabernacle now rested on each believer (2:3). The glory moved from a building to a people filled with the Holy Spirit.', 'Holy Spirit, rest on me with fire. Make me a living house of Your presence.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d13', 'plan-shekinah-glory-14', 13, 'From glory to glory', '2 Corinthians 3-4', 'Beholding the glory of the Lord with unveiled face, we are being transformed into the same image from glory to glory (3:18). We carry this treasure in clay jars (4:7).', 'Lord, as I look at You, change me. Shine through my weakness.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-shekinah-glory-14-d14', 'plan-shekinah-glory-14', 14, 'The city that needs no sun', 'Revelation 21-22', 'The glory of God illuminates the city and the Lamb is its lamp (21:23). The story ends where it began: God dwelling with His people, face to face.', 'Lord Jesus, come. Until then, let Your glory be my light every day.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-holy-spirit-21', 'Walking with the Holy Spirit', 'Three weeks getting to know the Holy Spirit as a Person: His work in creation, in the prophets, in Jesus, at Pentecost and in your daily life. Includes the gifts, the fruit and how to be led by Him.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-holy-spirit-21.jpg', 21, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d1', 'plan-holy-spirit-21', 1, 'Hovering over the waters', 'Genesis 1', 'The Spirit of God was hovering over the waters (1:2) before light was spoken. Where there is chaos, the Spirit is present and ready to bring order and life.', 'Holy Spirit, hover over the unformed places in my life. Bring order and light.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d2', 'plan-holy-spirit-21', 2, 'Filled for craftsmanship', 'Exodus 31; Exodus 35', 'Bezalel was filled with the Spirit for skill, wisdom and craftsmanship (31:3). The Spirit empowers practical work, not only preaching.', 'Holy Spirit, fill my work with Your wisdom and skill.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d3', 'plan-holy-spirit-21', 3, 'The Spirit on the seventy', 'Numbers 11', 'God took of the Spirit on Moses and put it on seventy elders (11:25). Moses longed that all the Lord''s people were prophets (11:29), a longing fulfilled at Pentecost.', 'Lord, pour Your Spirit on all of us, not only on leaders.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d4', 'plan-holy-spirit-21', 4, 'Not by might', 'Zechariah 4', '''Not by might nor by power, but by My Spirit,'' says the Lord (4:6). The mountain before Zerubbabel became a plain. Small beginnings are not despised.', 'Holy Spirit, I stop striving in my own strength. Do by Your power what I cannot do.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d5', 'plan-holy-spirit-21', 5, 'Dry bones live', 'Ezekiel 36-37', 'God promised a new heart and His Spirit within (36:26-27). In the valley of dry bones, breath came and they stood up, an exceedingly great army (37:10).', 'Breath of God, blow on every dry place in me and in our church.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d6', 'plan-holy-spirit-21', 6, 'I will pour out My Spirit', 'Joel 2', 'Sons and daughters will prophesy, old men will dream, young men will see visions (2:28). The promise has no age, gender or class limit.', 'Lord, pour Your Spirit on our sons and daughters. Give us dreams and visions.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d7', 'plan-holy-spirit-21', 7, 'Conceived by the Spirit', 'Luke 1-2', 'The Holy Spirit came upon Mary and the power of the Most High overshadowed her (1:35). Elizabeth, Zechariah and Simeon were all filled with the Spirit.', 'Holy Spirit, overshadow me. Let what is impossible become possible.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d8', 'plan-holy-spirit-21', 8, 'Anointed to preach', 'Luke 3-4', 'The Spirit descended on Jesus like a dove; He returned ''in the power of the Spirit'' and read: ''The Spirit of the Lord is upon Me'' (4:18).', 'Spirit of the Lord, anoint me to bring good news to the poor and freedom to captives.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d9', 'plan-holy-spirit-21', 9, 'Rivers of living water', 'John 7', '''Out of his heart will flow rivers of living water.'' This He spoke concerning the Spirit (7:38-39). The Spirit is not a puddle; He is a river.', 'Jesus, I am thirsty. Let rivers of Your Spirit flow out of me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d10', 'plan-holy-spirit-21', 10, 'Another Helper', 'John 14-16', 'Jesus promised another Helper who would be with us forever, teach us all things, testify of Him and guide us into all truth (14:16, 26; 16:13).', 'Holy Spirit, my Helper, teach me today and guide me into truth.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d11', 'plan-holy-spirit-21', 11, 'Wait for the promise', 'Acts 1', '''You shall receive power when the Holy Spirit has come upon you, and you shall be My witnesses'' (1:8). The disciples waited together in prayer.', 'Lord, I wait on You. Clothe me with power to be Your witness.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d12', 'plan-holy-spirit-21', 12, 'Pentecost', 'Acts 2', 'A sound from heaven, tongues of fire, other languages, and Peter''s sermon: three thousand were added that day (2:41). The promise is for you and your children (2:39).', 'Holy Spirit, fill me afresh. Let our church be a Pentecost church.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d13', 'plan-holy-spirit-21', 13, 'Boldness in prayer', 'Acts 4', 'After threats, the believers prayed; the place was shaken and they spoke the word with boldness (4:31). Opposition became fuel for prayer.', 'Lord, when I face opposition, shake the place and give me boldness.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d14', 'plan-holy-spirit-21', 14, 'Led by the Spirit', 'Acts 8; Acts 10', 'The Spirit told Philip, ''Go near this chariot'' (8:29) and told Peter to go with the men from Cornelius (10:19). The Spirit leads people to people.', 'Holy Spirit, lead me to the person You want me to meet today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d15', 'plan-holy-spirit-21', 15, 'Life in the Spirit', 'Romans 8', 'Those who are led by the Spirit of God are sons of God (8:14). He helps in our weakness and intercedes with groanings too deep for words (8:26).', 'Holy Spirit, help me pray when I don''t know how. Lead me as a son.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d16', 'plan-holy-spirit-21', 16, 'Gifts for the body', '1 Corinthians 12', 'To each one is given a manifestation of the Spirit for the common good (12:7): wisdom, knowledge, faith, healing, miracles, prophecy, discernment, tongues and interpretation.', 'Holy Spirit, release Your gifts through me to build up others.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d17', 'plan-holy-spirit-21', 17, 'The more excellent way', '1 Corinthians 13-14', 'Without love, gifts are noise (13:1). Pursue love, and desire spiritual gifts, especially prophecy that edifies, exhorts and comforts (14:1-3).', 'Lord, make love the root of everything I do in Your power.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d18', 'plan-holy-spirit-21', 18, 'Walk by the Spirit', 'Galatians 5', 'Walk by the Spirit and you will not fulfil the desires of the flesh (5:16). His fruit grows as we keep in step with Him (5:25).', 'Holy Spirit, I choose to keep in step with You today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d19', 'plan-holy-spirit-21', 19, 'Sealed and filled', 'Ephesians 1; Ephesians 5', 'You were sealed with the Holy Spirit of promise (1:13). Be continually filled with the Spirit, speaking in psalms, hymns and spiritual songs (5:18-19).', 'Holy Spirit, fill me again today. Put a song in my heart.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d20', 'plan-holy-spirit-21', 20, 'Do not grieve or quench', 'Ephesians 4; 1 Thessalonians 5', 'Do not grieve the Holy Spirit (Ephesians 4:30); do not quench the Spirit or despise prophecies (1 Thessalonians 5:19-20). He is a Person who can be honoured or hurt.', 'Holy Spirit, forgive me where I have grieved You. I honour You in my words and choices.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-holy-spirit-21-d21', 'plan-holy-spirit-21', 21, 'The Spirit and the Bride say come', 'Revelation 22', '''The Spirit and the bride say, Come!'' (22:17). The Spirit''s final work in Scripture is an invitation, and He invites you to share it.', 'Holy Spirit, make me part of Your invitation. Let me say ''Come'' to the thirsty.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-prayer-14', 'Prayer That Moves Heaven', 'Fourteen days learning to pray from the great prayers of the Bible: Abraham, Moses, Hannah, Elijah, Daniel, Nehemiah, Jesus and the early church. Each day ends with a guided prayer you can pray out loud.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-prayer-14.jpg', 14, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d1', 'plan-prayer-14', 1, 'Abraham bargains for a city', 'Genesis 18', 'Abraham drew near and asked again and again for Sodom (18:23-32). Prayer is friendship with God that dares to ask on behalf of others.', 'Lord, I draw near as Your friend. I stand in the gap for my family and my city.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d2', 'plan-prayer-14', 2, 'Jacob wrestles until blessed', 'Genesis 32', '''I will not let You go unless You bless me'' (32:26). Jacob came out limping but with a new name. Persistent prayer changes the one who prays.', 'Lord, I will not let go. Bless me and change me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d3', 'plan-prayer-14', 3, 'Moses stands in the gap', 'Exodus 32', 'When Israel sinned, Moses pleaded for them and God relented (32:11-14). Intercession appeals to God''s character and promises.', 'Lord, remember Your promises. Have mercy on our nation.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d4', 'plan-prayer-14', 4, 'Hannah pours out her soul', '1 Samuel 1-2', 'Hannah prayed in bitterness and poured out her soul before the Lord (1:15). She went away and was no longer sad, and later sang of God who lifts the humble.', 'Lord, I pour out my heart before You. I leave my burden here.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d5', 'plan-prayer-14', 5, 'Solomon asks for wisdom', '1 Kings 3', '''Ask! What shall I give you?'' Solomon asked for an understanding heart, and God gave him what he did not ask for as well (3:5-13).', 'Lord, give me wisdom for the responsibilities You have given me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d6', 'plan-prayer-14', 6, 'Elijah prays for fire and rain', '1 Kings 18', 'Elijah prayed a short prayer and fire fell; then he bowed seven times until a small cloud rose (18:36-44). He was a man like us (James 5:17).', 'Lord, answer by fire. I will keep praying until I see the cloud.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d7', 'plan-prayer-14', 7, 'Jehoshaphat: our eyes are on You', '2 Chronicles 20', '''We do not know what to do, but our eyes are upon You'' (20:12). They sent the singers ahead and God set ambushes against the enemy.', 'Lord, when I don''t know what to do, my eyes are on You. I praise You before the victory.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d8', 'plan-prayer-14', 8, 'Nehemiah weeps and plans', 'Nehemiah 1-2', 'Nehemiah mourned, fasted and prayed for days, then prayed an arrow prayer before the king (2:4). Prayer prepares us to act.', 'Lord, break my heart for what breaks Yours, then give me favour to act.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d9', 'plan-prayer-14', 9, 'Daniel prays three times a day', 'Daniel 6; Daniel 9', 'Daniel kept his windows open toward Jerusalem even when it was illegal (6:10). He confessed the sins of his people and Gabriel was sent at the beginning of his prayer (9:23).', 'Lord, make prayer my daily habit, whatever it costs.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d10', 'plan-prayer-14', 10, 'Lord, teach us to pray', 'Matthew 6; Luke 11', 'Jesus gave a pattern: Father, hallowed be Your name, Your kingdom come, daily bread, forgiveness, deliverance. Ask, seek and knock (Luke 11:9).', 'Our Father in heaven, hallowed be Your name. Your kingdom come in my life today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d11', 'plan-prayer-14', 11, 'Gethsemane: not my will', 'Matthew 26; Luke 22', 'Jesus prayed in agony, ''Not My will, but Yours be done'' (Luke 22:42), and an angel strengthened Him. Surrender is the deepest prayer.', 'Father, not my will but Yours. Strengthen me to obey.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d12', 'plan-prayer-14', 12, 'Jesus prays for you', 'John 17', 'Jesus prayed for those who would believe through the disciples'' word (17:20), which means He prayed for you, that you would be one and see His glory.', 'Jesus, thank You for praying for me. Make Your church one.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d13', 'plan-prayer-14', 13, 'The church that prayed Peter out', 'Acts 12', 'Peter was in prison, ''but constant prayer was offered to God for him by the church'' (12:5). An angel opened the gates while they were still praying.', 'Lord, as a church we pray for those in prisons of every kind. Open the gates.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-prayer-14-d14', 'plan-prayer-14', 14, 'Pray without ceasing', 'Ephesians 6; Philippians 4', 'Pray always with all prayer and supplication in the Spirit (Ephesians 6:18). Be anxious for nothing; with thanksgiving let your requests be known, and peace will guard you (Philippians 4:6-7).', 'Lord, I bring every worry to You with thanksgiving. Guard my heart with Your peace.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-heroes-of-faith-12', 'Heroes of Faith', 'Twelve days walking through the hall of faith in Hebrews 11, reading each hero''s story in full. See how ordinary, flawed people pleased God by trusting Him, and learn what faith looks like on a Monday morning.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-heroes-of-faith-12.jpg', 12, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d1', 'plan-heroes-of-faith-12', 1, 'What faith is', 'Hebrews 11', 'Faith is the substance of things hoped for, the evidence of things not seen (11:1). Without faith it is impossible to please God (11:6).', 'Lord, increase my faith. I believe You are, and You reward those who seek You.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d2', 'plan-heroes-of-faith-12', 2, 'Abel and Enoch', 'Genesis 4-5', 'Abel offered a better sacrifice; Enoch walked with God and was not, for God took him (5:24). Faith worships rightly and walks daily.', 'Lord, let my worship please You and let me walk with You every day.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d3', 'plan-heroes-of-faith-12', 3, 'Noah builds in a dry land', 'Genesis 6-8', 'Noah, warned of things not yet seen, built an ark (Hebrews 11:7). He obeyed for decades without seeing rain.', 'Lord, help me obey what You said even before I see it.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d4', 'plan-heroes-of-faith-12', 4, 'Abraham goes out not knowing', 'Genesis 12-13', 'Abraham obeyed and went out, not knowing where he was going (Hebrews 11:8). Faith follows the voice, not the map.', 'Lord, I will go where You lead, one step at a time.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d5', 'plan-heroes-of-faith-12', 5, 'Sarah laughs and receives', 'Genesis 18; Genesis 21', 'Sarah laughed at the promise, then received strength to conceive because she judged Him faithful who had promised (Hebrews 11:11). God turned her laughter into joy.', 'Lord, You are faithful. Turn my doubtful laughter into joyful laughter.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d6', 'plan-heroes-of-faith-12', 6, 'Moses chooses affliction', 'Exodus 2-3', 'Moses refused to be called the son of Pharaoh''s daughter, choosing to suffer with God''s people (Hebrews 11:24-26). He endured as seeing Him who is invisible.', 'Lord, help me choose You over comfort and status.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d7', 'plan-heroes-of-faith-12', 7, 'Through the Red Sea', 'Exodus 14-15', 'By faith they passed through the Red Sea as by dry land (Hebrews 11:29). ''Stand still and see the salvation of the Lord'' (Exodus 14:13).', 'Lord, open a way where there is no way. I will stand and see Your salvation.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d8', 'plan-heroes-of-faith-12', 8, 'The walls of Jericho', 'Joshua 6', 'By faith the walls fell after they were encircled seven days (Hebrews 11:30). Faith obeys instructions that look foolish.', 'Lord, I will keep walking and shouting until my walls fall.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d9', 'plan-heroes-of-faith-12', 9, 'Rahab the protector', 'Joshua 2', 'Rahab hid the spies and tied a scarlet cord in her window. A woman with a past became an ancestor of Jesus (Matthew 1:5).', 'Lord, thank You that my past does not cancel Your plan. I hang my scarlet cord of faith.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d10', 'plan-heroes-of-faith-12', 10, 'Gideon''s three hundred', 'Judges 6-7', 'God reduced Gideon''s army to three hundred so that Israel could not boast (7:2). Weakness made strong is a mark of faith (Hebrews 11:34).', 'Lord, use my weakness so that the glory is Yours.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d11', 'plan-heroes-of-faith-12', 11, 'Samuel and David', '1 Samuel 16-17', 'Samuel anointed the youngest son; David faced Goliath ''in the name of the Lord of hosts'' (17:45). Faith grows in hidden places before it shows in public.', 'Lord, I face my giant in Your name. Prepare me in secret for public victories.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-heroes-of-faith-12-d12', 'plan-heroes-of-faith-12', 12, 'The great cloud of witnesses', 'Hebrews 12', 'Since we are surrounded by so great a cloud of witnesses, let us lay aside every weight and run with endurance, looking to Jesus (12:1-2).', 'Jesus, author and finisher of my faith, help me lay aside every weight and finish my race.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-fruit-of-the-spirit-9', 'The Fruit of the Spirit', 'Nine days, one fruit each day: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control. Each day reads a whole chapter that shows the fruit in action, with a practical step for the day.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-fruit-of-the-spirit-9.jpg', 9, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d1', 'plan-fruit-of-the-spirit-9', 1, 'Love', '1 Corinthians 13', 'Love is patient and kind, does not envy or boast, bears all things and never fails (13:4-8). Today: do one hidden act of love for someone who cannot repay you.', 'Holy Spirit, grow Your love in me. Love through me where I find it hard to love.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d2', 'plan-fruit-of-the-spirit-9', 2, 'Joy', 'Philippians 4', 'Paul wrote ''Rejoice in the Lord always'' from prison (4:4). Joy is not the absence of trouble but the presence of the Lord. Today: thank God for five specific things.', 'Lord, fill me with joy that circumstances cannot steal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d3', 'plan-fruit-of-the-spirit-9', 3, 'Peace', 'John 14', '''Peace I leave with you, My peace I give to you... let not your heart be troubled'' (14:27). Today: bring your biggest worry to God and leave it there.', 'Prince of Peace, guard my heart and mind. Let Your peace rule in me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d4', 'plan-fruit-of-the-spirit-9', 4, 'Patience', 'James 5', 'See how the farmer waits patiently for the precious fruit of the earth (5:7). Patience trusts God''s timing. Today: respond slowly when someone frustrates you.', 'Lord, teach me to wait well and to bear with others as You bear with me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d5', 'plan-fruit-of-the-spirit-9', 5, 'Kindness', 'Luke 10', 'The Samaritan saw, had compassion, went to him and bound up his wounds (10:33-34). Kindness crosses the road. Today: help someone outside your usual circle.', 'Lord, open my eyes to the wounded on my road and give me a kind heart.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d6', 'plan-fruit-of-the-spirit-9', 6, 'Goodness', 'Romans 12', 'Abhor what is evil, cling to what is good; overcome evil with good (12:9, 21). Goodness is moral beauty in action. Today: answer an insult with a blessing.', 'Lord, make me good, not only nice. Help me overcome evil with good.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d7', 'plan-fruit-of-the-spirit-9', 7, 'Faithfulness', 'Matthew 25', '''Well done, good and faithful servant; you were faithful over a few things'' (25:21). Faithfulness is doing small things reliably. Today: finish one promise you have delayed.', 'Lord, make me faithful in small things so You can trust me with more.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d8', 'plan-fruit-of-the-spirit-9', 8, 'Gentleness', 'Matthew 11; Galatians 6', 'Jesus said, ''I am gentle and lowly in heart'' (Matthew 11:29). Restore a fallen brother in a spirit of gentleness (Galatians 6:1). Today: speak softly in a tense moment.', 'Jesus, give me Your gentle heart. Make my words healing, not harsh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-fruit-of-the-spirit-9-d9', 'plan-fruit-of-the-spirit-9', 9, 'Self-control', 'Proverbs 25; 1 Corinthians 9', 'Whoever has no rule over his own spirit is like a city broken down, without walls (Proverbs 25:28). Paul disciplined his body like an athlete (1 Corinthians 9:27). Today: say no to one craving.', 'Holy Spirit, strengthen my will. Rule over my appetites, words and time.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-names-of-god-10', 'The Names of God', 'Ten days with the names God revealed for Himself. Each name answers a human need: provision, healing, peace, victory, presence. Read the chapter where the name was first revealed and pray it back to Him.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-names-of-god-10.jpg', 10, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d1', 'plan-names-of-god-10', 1, 'Elohim: the Creator', 'Genesis 1', '''In the beginning God (Elohim) created the heavens and the earth'' (1:1). The mighty Creator holds everything together, including your life.', 'Elohim, You created all things. I trust the One who made me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d2', 'plan-names-of-god-10', 2, 'El Shaddai: God Almighty', 'Genesis 17', '''I am Almighty God; walk before Me and be blameless'' (17:1). At ninety-nine, Abram received a new name and a promise only the Almighty could keep.', 'El Shaddai, nothing is too hard for You. I walk before You today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d3', 'plan-names-of-god-10', 3, 'Jehovah Jireh: the Lord will provide', 'Genesis 22', 'On the mountain the Lord provided a ram in place of Isaac (22:14). He sees ahead and provides before we arrive.', 'Jehovah Jireh, You see my need before I do. I trust You to provide.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d4', 'plan-names-of-god-10', 4, 'Jehovah Rapha: the Lord who heals', 'Exodus 15', 'At Marah the bitter water was made sweet. ''I am the Lord who heals you'' (15:26). He heals bodies, hearts and bitter places.', 'Jehovah Rapha, heal me in body, soul and spirit. Make my bitter waters sweet.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d5', 'plan-names-of-god-10', 5, 'Jehovah Nissi: the Lord my banner', 'Exodus 17', 'While Moses'' hands were lifted, Israel prevailed. Moses built an altar: ''The Lord is my banner'' (17:15). Victory comes under His flag.', 'Jehovah Nissi, I fight under Your banner. Hold up my hands when I grow weary.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d6', 'plan-names-of-god-10', 6, 'Jehovah Shalom: the Lord is peace', 'Judges 6', 'A frightened Gideon met the Angel of the Lord and built an altar called ''The Lord is peace'' (6:24). God''s peace came before the battle.', 'Jehovah Shalom, calm my fears and give me peace before my battles.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d7', 'plan-names-of-god-10', 7, 'Jehovah Rohi: the Lord my shepherd', 'Psalm 23; John 10', '''The Lord is my shepherd; I shall not want'' (Psalm 23:1). Jesus is the good shepherd who lays down His life for the sheep (John 10:11).', 'Good Shepherd, lead me, restore my soul and walk with me through every valley.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d8', 'plan-names-of-god-10', 8, 'Jehovah Tsidkenu: the Lord our righteousness', 'Jeremiah 23; 2 Corinthians 5', 'A righteous Branch would be called ''The Lord our righteousness'' (Jeremiah 23:6). God made Him who knew no sin to be sin for us (2 Corinthians 5:21).', 'Jehovah Tsidkenu, I stand in Your righteousness, not my own.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d9', 'plan-names-of-god-10', 9, 'Jehovah Shammah: the Lord is there', 'Ezekiel 48; Matthew 28', 'The city''s name will be ''The Lord is there'' (Ezekiel 48:35). Jesus promised, ''I am with you always'' (Matthew 28:20).', 'Jehovah Shammah, You are here. I will not fear, for You are with me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-names-of-god-10-d10', 'plan-names-of-god-10', 10, 'Immanuel: God with us', 'Isaiah 7; Matthew 1', '''The virgin shall conceive and bear a Son, and shall call His name Immanuel'' (Isaiah 7:14; Matthew 1:23). Every name of God comes close in Jesus.', 'Jesus, Immanuel, thank You for coming close. Be with me in every part of today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-david-14', 'David: A Heart After God', 'Two weeks through the life of David: shepherd, giant-slayer, fugitive, king, sinner, worshipper. Read his story alongside the psalms he wrote in those seasons, and learn what it means to have a heart after God.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-david-14.jpg', 14, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d1', 'plan-david-14', 1, 'Chosen in the field', '1 Samuel 16', 'Man looks at the outward appearance, but the Lord looks at the heart (16:7). David was anointed while still keeping sheep.', 'Lord, look at my heart and shape it. Prepare me in my hidden season.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d2', 'plan-david-14', 2, 'The Shepherd''s song', 'Psalm 23; Psalm 8', 'David learned God as shepherd while being a shepherd. Under the night sky he asked, ''What is man that You are mindful of him?'' (8:4).', 'Lord, You are my shepherd. Thank You for being mindful of me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d3', 'plan-david-14', 3, 'Goliath falls', '1 Samuel 17', '''You come to me with a sword... but I come to you in the name of the Lord of hosts'' (17:45). Private victories over lions prepared David for public victory.', 'Lord, I face what intimidates me in Your name.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d4', 'plan-david-14', 4, 'Friendship and jealousy', '1 Samuel 18-20', 'Jonathan loved David as his own soul, while Saul''s jealousy grew. God gives covenant friends for hard seasons.', 'Lord, thank You for true friends. Guard my heart from jealousy.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d5', 'plan-david-14', 5, 'Hiding in caves', '1 Samuel 22; Psalm 57', 'In the cave of Adullam the distressed and indebted gathered to David. He sang, ''My heart is steadfast, O God'' (Psalm 57:7).', 'Lord, even in my cave my heart is steadfast. Make me a refuge for others.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d6', 'plan-david-14', 6, 'Sparing Saul', '1 Samuel 24; 1 Samuel 26', 'David would not touch the Lord''s anointed even when he could. He trusted God to promote him in His time.', 'Lord, I refuse to take shortcuts. I trust You to lift me up in Your time.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d7', 'plan-david-14', 7, 'Strength in the Lord', '1 Samuel 30', 'When all was lost at Ziklag and his men spoke of stoning him, ''David strengthened himself in the Lord his God'' (30:6), then recovered all.', 'Lord, when everything falls apart, I strengthen myself in You. Help me recover all.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d8', 'plan-david-14', 8, 'King at last', '2 Samuel 5; Psalm 18', 'David became king over all Israel at thirty after years of waiting. He sang, ''The Lord is my rock, my fortress and my deliverer'' (Psalm 18:2).', 'Lord, You are my rock. Thank You for keeping Your promises.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d9', 'plan-david-14', 9, 'Dancing before the Lord', '2 Samuel 6', 'David danced with all his might as the ark came into Jerusalem, and refused to be ashamed of worship (6:14, 22).', 'Lord, I will worship You with all my might and without shame.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d10', 'plan-david-14', 10, 'A house forever', '2 Samuel 7', 'David wanted to build God a house; God promised to build David a house and a throne forever, fulfilled in Jesus, the Son of David.', 'Lord, who am I that You have brought me this far? Thank You for Your promises.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d11', 'plan-david-14', 11, 'The fall', '2 Samuel 11-12', 'A rooftop look became adultery and murder. Nathan''s words pierced: ''You are the man'' (12:7). Even great men need guarded hearts.', 'Lord, guard my eyes and my heart. Send me Nathans who tell me the truth.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d12', 'plan-david-14', 12, 'A broken and contrite heart', 'Psalm 51; Psalm 32', '''Create in me a clean heart, O God'' (51:10). David did not excuse his sin; he confessed it and found the joy of forgiveness (32:1-5).', 'Lord, create in me a clean heart. Restore to me the joy of Your salvation.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d13', 'plan-david-14', 13, 'Consequences and mercy', '2 Samuel 15-18', 'Absalom''s rebellion brought grief, yet David trusted God''s mercy: ''Let Him do to me as seems good to Him'' (15:26).', 'Lord, in seasons of consequence, I still trust Your mercy.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-david-14-d14', 'plan-david-14', 14, 'Last words and a legacy', '2 Samuel 23; 1 Chronicles 29', 'David''s last words celebrate God''s everlasting covenant; he gave generously for the temple his son would build (1 Chronicles 29).', 'Lord, let me finish well and leave a legacy of worship and generosity.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-stewardship-10', 'Kingdom Stewardship', 'Ten days on money, work and generosity from God''s perspective. Learn to see everything as His, to work with excellence, to give cheerfully, and to trust Him as your source. Practical and Bible-based.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-stewardship-10.jpg', 10, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d1', 'plan-stewardship-10', 1, 'Everything belongs to God', 'Psalm 24; Psalm 50', '''The earth is the Lord''s, and all its fullness'' (24:1). The cattle on a thousand hills are His (50:10). We are managers, not owners.', 'Lord, everything I have is Yours. Teach me to manage it well.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d2', 'plan-stewardship-10', 2, 'Work as worship', 'Genesis 2; Colossians 3', 'God put man in the garden to work it and keep it (Genesis 2:15). Whatever you do, work heartily, as for the Lord (Colossians 3:23).', 'Lord, let my work today be worship to You.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d3', 'plan-stewardship-10', 3, 'Honour with the firstfruits', 'Proverbs 3', 'Honour the Lord with your possessions and with the firstfruits of all your increase (3:9-10). First things show what comes first.', 'Lord, I honour You first with what You give me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d4', 'plan-stewardship-10', 4, 'Bring the whole tithe', 'Malachi 3', '''Bring all the tithes into the storehouse... and try Me now in this'' (3:10). God invites us to trust Him with our giving.', 'Lord, I trust You with my giving. Open the windows of heaven over our church.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d5', 'plan-stewardship-10', 5, 'The cheerful giver', '2 Corinthians 8-9', 'God loves a cheerful giver; he who sows bountifully will reap bountifully (9:6-7). The Macedonians gave out of deep poverty with great joy.', 'Lord, make me a cheerful, generous giver.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d6', 'plan-stewardship-10', 6, 'The parable of the talents', 'Matthew 25', 'Each servant received according to his ability; the faithful ones doubled what they had. Fear buried the talent (25:25).', 'Lord, I will not bury what You gave me. Help me multiply it for Your kingdom.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d7', 'plan-stewardship-10', 7, 'Diligence and planning', 'Proverbs 6; Proverbs 21', 'Go to the ant, consider her ways (6:6). The plans of the diligent lead surely to plenty (21:5). Plan, save and work hard.', 'Lord, make me diligent and wise in my plans.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d8', 'plan-stewardship-10', 8, 'Freedom from debt and greed', 'Proverbs 22; Luke 12', 'The borrower is servant to the lender (Proverbs 22:7). ''Beware of covetousness; life does not consist in the abundance of possessions'' (Luke 12:15).', 'Lord, free me from debt and greed. Let my life be rich toward You.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d9', 'plan-stewardship-10', 9, 'Contentment', 'Philippians 4; 1 Timothy 6', 'Paul learned to be content in plenty and in want (Philippians 4:11-13). Godliness with contentment is great gain (1 Timothy 6:6).', 'Lord, teach me contentment, and let my security be in You alone.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-stewardship-10-d10', 'plan-stewardship-10', 10, 'Seek first the kingdom', 'Matthew 6', 'Do not worry about what you will eat or wear; seek first the kingdom of God and His righteousness, and all these things will be added (6:33).', 'Father, I seek Your kingdom first. I trust You to add everything I need.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plans (id, title, description, image_url, duration_days, is_active) VALUES ('plan-cross-and-tomb-8', 'The Cross and the Empty Tomb', 'Eight days walking with Jesus from the triumphal entry to the resurrection appearances. Ideal before Easter or any time you want to fall in love again with what Jesus did for you.', 'https://shekinah-sons-global.onrender.com/api/v1/covers/plans/plan-cross-and-tomb-8.jpg', 8, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d1', 'plan-cross-and-tomb-8', 1, 'The King on a donkey', 'Matthew 21; Zechariah 9', 'Jesus entered Jerusalem humble and riding on a donkey, fulfilling Zechariah 9:9. The crowds shouted ''Hosanna!'' and He cleansed the temple.', 'Jesus, my King, ride into my heart and cleanse my temple.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d2', 'plan-cross-and-tomb-8', 2, 'The suffering Servant', 'Isaiah 53', 'He was wounded for our transgressions, bruised for our iniquities; by His stripes we are healed (53:5). Written centuries before the cross.', 'Jesus, thank You for carrying my sin and sickness. By Your stripes I am healed.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d3', 'plan-cross-and-tomb-8', 3, 'The last supper', 'John 13; Luke 22', 'Jesus washed His disciples'' feet, then broke bread: ''This is My body given for you'' (Luke 22:19). Love served before it suffered.', 'Lord Jesus, thank You for Your body and blood. Teach me to serve as You served.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d4', 'plan-cross-and-tomb-8', 4, 'Gethsemane and betrayal', 'Mark 14', 'In the garden Jesus prayed, ''Abba, Father, all things are possible for You; take this cup away from Me. Nevertheless, not what I will'' (14:36). He was betrayed with a kiss.', 'Jesus, thank You for choosing the cup for me. Make me faithful where others fall away.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d5', 'plan-cross-and-tomb-8', 5, 'Trials and denial', 'Luke 22-23', 'Peter denied Him three times, and the Lord turned and looked at Peter (22:61). Jesus was declared innocent and still condemned.', 'Lord, when I have failed You, let Your look lead me to repentance, not shame.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d6', 'plan-cross-and-tomb-8', 6, 'It is finished', 'John 19; Psalm 22', '''It is finished!'' (John 19:30). Psalm 22 begins ''My God, why have You forsaken me?'' and ends with the nations worshipping. The debt is paid in full.', 'Jesus, it is finished. I receive the full payment You made for me.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d7', 'plan-cross-and-tomb-8', 7, 'He is risen', 'Matthew 28; John 20', '''He is not here; for He is risen, as He said'' (Matthew 28:6). Mary heard her name and knew Him (John 20:16).', 'Risen Lord, speak my name. Let resurrection life fill me today.') ON CONFLICT (id) DO NOTHING;
INSERT INTO reading_plan_days (id, plan_id, day_number, title, reference, description, prayer_prompt) VALUES ('plan-cross-and-tomb-8-d8', 'plan-cross-and-tomb-8', 8, 'Burning hearts', 'Luke 24; 1 Corinthians 15', 'On the road to Emmaus their hearts burned as He opened the Scriptures (Luke 24:32). Because He lives, death has lost its sting (1 Corinthians 15:55).', 'Jesus, walk with me and open the Scriptures to me. Make my heart burn.') ON CONFLICT (id) DO NOTHING;
